[
  {
    "routine_name": "accept_invitation",
    "routine_definition": "\nDECLARE\n  inv record;\nBEGIN\n  SELECT * INTO inv FROM public.invitations\n  WHERE token = token_value AND invite_status = 'pending'\n  LIMIT 1;\n\n  IF inv IS NULL THEN\n    RETURN json_build_object('success', false, 'error', 'Invalid or already used invitation');\n  END IF;\n\n  IF inv.expires_at < now() THEN\n    UPDATE public.invitations SET invite_status = 'expired' WHERE id = inv.id;\n    RETURN json_build_object('success', false, 'error', 'Invitation has expired');\n  END IF;\n\n  UPDATE public.invitations\n  SET invite_status = 'accepted', accepted_at = now()\n  WHERE id = inv.id;\n\n  RETURN json_build_object('success', true, 'invitation_id', inv.id::text);\nEND;\n"
  },
  {
    "routine_name": "auth_user_role",
    "routine_definition": "\r\n  SELECT role FROM public.users WHERE id = auth.uid();\r\n"
  },
  {
    "routine_name": "auth_user_tenant_id",
    "routine_definition": "\r\n  SELECT tenant_id FROM public.users WHERE id = auth.uid();\r\n"
  },
  {
    "routine_name": "check_rate_limit",
    "routine_definition": "\nDECLARE\n  attempt_count int;\nBEGIN\n  -- Clean old entries\n  DELETE FROM public.rate_limits\n  WHERE attempted_at < now() - (p_window_minutes || ' minutes')::interval;\n\n  -- Count recent attempts\n  SELECT COUNT(*) INTO attempt_count\n  FROM public.rate_limits\n  WHERE identifier = p_identifier\n    AND action = p_action\n    AND attempted_at > now() - (p_window_minutes || ' minutes')::interval;\n\n  IF attempt_count >= p_max_attempts THEN\n    RETURN false;\n  END IF;\n\n  -- Record this attempt\n  INSERT INTO public.rate_limits (identifier, action) VALUES (p_identifier, p_action);\n  RETURN true;\nEND;\n"
  },
  {
    "routine_name": "create_team_invitation",
    "routine_definition": "\r\nDECLARE\r\n  v_token UUID;\r\n  v_invitation_id UUID;\r\n  v_inviter RECORD;\r\n  v_tenant RECORD;\r\nBEGIN\r\n \r\n  -- Validate role\r\n  IF p_role NOT IN ('tenant_admin', 'accountant', 'viewer') THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Invalid role');\r\n  END IF;\r\n \r\n  -- Check if already invited and pending\r\n  IF EXISTS (\r\n    SELECT 1 FROM invitations\r\n    WHERE email = p_email\r\n      AND tenant_id = p_tenant_id\r\n      AND status = 'pending'\r\n      AND expires_at > NOW()\r\n  ) THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Invitation already sent to this email');\r\n  END IF;\r\n \r\n  -- Get inviter and tenant details for the email\r\n  SELECT first_name, last_name INTO v_inviter FROM profiles WHERE id = p_invited_by;\r\n  SELECT company_name INTO v_tenant FROM tenants WHERE id = p_tenant_id;\r\n \r\n  -- Generate unique token\r\n  v_token := gen_random_uuid();\r\n \r\n  -- Create invitation record\r\n  INSERT INTO invitations (\r\n    tenant_id, email, role, token,\r\n    invited_by, first_name, last_name,\r\n    status, expires_at, created_at\r\n  ) VALUES (\r\n    p_tenant_id, lower(trim(p_email)), p_role, v_token,\r\n    p_invited_by, p_first_name, p_last_name,\r\n    'pending', NOW() + INTERVAL '7 days', NOW()\r\n  ) RETURNING id INTO v_invitation_id;\r\n \r\n  -- Log the action\r\n  INSERT INTO activity_logs (\r\n    tenant_id, user_id, action, entity_type, entity_id, details, created_at\r\n  ) VALUES (\r\n    p_tenant_id, p_invited_by, 'team_member_invited', 'invitation', v_invitation_id,\r\n    jsonb_build_object('email', p_email, 'role', p_role),\r\n    NOW()\r\n  );\r\n \r\n  -- Return everything the Edge Function needs to send the email\r\n  RETURN jsonb_build_object(\r\n    'success', true,\r\n    'invitation_id', v_invitation_id,\r\n    'token', v_token,\r\n    'email', p_email,\r\n    'role', p_role,\r\n    'inviter_name', COALESCE(v_inviter.first_name || ' ' || v_inviter.last_name, 'Your Team'),\r\n    'company_name', v_tenant.company_name,\r\n    'first_name', p_first_name\r\n  );\r\n \r\nEXCEPTION WHEN OTHERS THEN\r\n  RETURN jsonb_build_object('success', false, 'error', SQLERRM);\r\nEND;\r\n"
  },
  {
    "routine_name": "custom_access_token_hook",
    "routine_definition": "\r\nDECLARE\r\n  user_id   uuid;\r\n  usr       record;\r\n  claims    jsonb;\r\nBEGIN\r\n  -- Parse user ID safely\r\n  BEGIN\r\n    user_id := (event ->> 'userId')::uuid;\r\n  EXCEPTION WHEN OTHERS THEN\r\n    RETURN event;\r\n  END;\r\n\r\n  -- Query users table with RLS fully bypassed\r\n  BEGIN\r\n    SELECT role, tenant_id::text, COALESCE(is_active, true) AS is_active\r\n    INTO usr\r\n    FROM public.users\r\n    WHERE id = user_id;\r\n  EXCEPTION WHEN OTHERS THEN\r\n    RETURN event;\r\n  END;\r\n\r\n  -- No profile found — don't block login\r\n  IF usr IS NULL OR usr.role IS NULL THEN\r\n    RETURN event;\r\n  END IF;\r\n\r\n  -- Embed claims\r\n  BEGIN\r\n    claims := COALESCE(event -> 'claims', '{}'::jsonb);\r\n    claims := jsonb_set(\r\n      claims,\r\n      '{app_metadata}',\r\n      COALESCE(claims -> 'app_metadata', '{}'::jsonb)\r\n      || jsonb_build_object(\r\n          'role',      usr.role,\r\n          'tenant_id', COALESCE(usr.tenant_id, ''),\r\n          'is_active', usr.is_active\r\n        )\r\n    );\r\n    RETURN jsonb_set(event, '{claims}', claims);\r\n  EXCEPTION WHEN OTHERS THEN\r\n    RETURN event;\r\n  END;\r\nEND;\r\n"
  },
  {
    "routine_name": "expire_old_invitations",
    "routine_definition": "\n  WITH updated AS (\n    UPDATE public.invitations\n    SET invite_status = 'expired'\n    WHERE invite_status = 'pending' AND expires_at < now()\n    RETURNING id\n  )\n  SELECT COUNT(*)::integer FROM updated;\n"
  },
  {
    "routine_name": "generate_dispute_email",
    "routine_definition": "\r\nDECLARE\r\n  v_log          RECORD;\r\n  v_tenant       RECORD;\r\n  v_subject      TEXT;\r\n  v_body         TEXT;\r\n  v_dispute_id   UUID;\r\n  v_greeting     TEXT;\r\n  v_intro        TEXT;\r\n  v_detail_block TEXT;\r\n  v_demand       TEXT;\r\n  v_closing      TEXT;\r\n  v_today        TEXT;\r\nBEGIN\r\n\r\n  -- Get the audit log + shipment details\r\n  SELECT\r\n    al.*,\r\n    s.order_id,\r\n    s.origin_pincode,\r\n    s.destination_pincode,\r\n    s.shipment_date,\r\n    s.actual_weight,\r\n    s.length,\r\n    s.width,\r\n    s.height\r\n  INTO v_log\r\n  FROM audit_logs al\r\n  LEFT JOIN shipments s ON s.id = al.shipment_id\r\n  WHERE al.id = p_audit_log_id\r\n    AND al.tenant_id = p_tenant_id;\r\n\r\n  IF NOT FOUND THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Audit log not found');\r\n  END IF;\r\n\r\n  -- Get tenant company details\r\n  SELECT company_name, gstin INTO v_tenant\r\n  FROM tenants WHERE id = p_tenant_id;\r\n\r\n  -- Format today's date\r\n  v_today := TO_CHAR(NOW(), 'DD Month YYYY');\r\n\r\n  -- ============================================================\r\n  -- COURIER-SPECIFIC GREETING\r\n  -- Each major courier has a named billing team contact\r\n  -- ============================================================\r\n  v_greeting := CASE v_log.courier\r\n    WHEN 'Delhivery'    THEN 'Dear Delhivery Billing Disputes Team,'\r\n    WHEN 'Blue Dart'    THEN 'Dear Blue Dart Customer Billing Team,'\r\n    WHEN 'DTDC'         THEN 'Dear DTDC Billing Resolution Team,'\r\n    WHEN 'Ecom Express' THEN 'Dear Ecom Express Billing Team,'\r\n    WHEN 'XpressBees'   THEN 'Dear XpressBees Finance & Billing Team,'\r\n    WHEN 'Shadowfax'    THEN 'Dear Shadowfax Billing Support Team,'\r\n    WHEN 'Ekart'        THEN 'Dear Ekart Logistics Billing Team,'\r\n    ELSE                     'Dear Billing Disputes Team,'\r\n  END;\r\n\r\n  -- ============================================================\r\n  -- SUBJECT LINE based on discrepancy type\r\n  -- ============================================================\r\n  v_subject := CASE v_log.discrepancy_type\r\n    WHEN 'weight_mismatch' THEN\r\n      format('Billing Dispute — Weight Discrepancy | AWB: %s | Overcharge: Rs %.2f',\r\n        v_log.awb_number, v_log.overcharge_amount)\r\n    WHEN 'zone_mismatch' THEN\r\n      format('Billing Dispute — Zone Misclassification | AWB: %s | Overcharge: Rs %.2f',\r\n        v_log.awb_number, v_log.overcharge_amount)\r\n    WHEN 'rto_overcharge' THEN\r\n      format('Billing Dispute — RTO Overcharge | AWB: %s | Overcharge: Rs %.2f',\r\n        v_log.awb_number, v_log.overcharge_amount)\r\n    WHEN 'weight_zone_mismatch' THEN\r\n      format('Billing Dispute — Weight & Zone Discrepancy | AWB: %s | Overcharge: Rs %.2f',\r\n        v_log.awb_number, v_log.overcharge_amount)\r\n    ELSE\r\n      format('Billing Dispute — AWB: %s | Overcharge: Rs %.2f',\r\n        v_log.awb_number, v_log.overcharge_amount)\r\n  END;\r\n\r\n  -- ============================================================\r\n  -- INTRO PARAGRAPH — same for all types\r\n  -- ============================================================\r\n  v_intro := format(\r\n    'We are writing from %s (GSTIN: %s) regarding a billing discrepancy identified '\r\n    'in our shipment records for AWB number %s dispatched via %s. '\r\n    'After a thorough audit of our shipping invoices against our contracted rate card, '\r\n    'we have found that the charges billed do not match the agreed rates. '\r\n    'We request an immediate review and issuance of a credit note for the overcharged amount.',\r\n    v_tenant.company_name,\r\n    COALESCE(v_tenant.gstin, 'pending registration'),\r\n    v_log.awb_number,\r\n    v_log.courier\r\n  );\r\n\r\n  -- ============================================================\r\n  -- DETAIL BLOCK — specific to each discrepancy type\r\n  -- ============================================================\r\n  v_detail_block := CASE v_log.discrepancy_type\r\n\r\n    -- WEIGHT MISMATCH\r\n    WHEN 'weight_mismatch' THEN format(\r\n      'DISCREPANCY DETAILS — WEIGHT MISMATCH' || chr(10) ||\r\n      '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' || chr(10) ||\r\n      'AWB Number          : %s' || chr(10) ||\r\n      'Order ID            : %s' || chr(10) ||\r\n      'Shipment Date       : %s' || chr(10) ||\r\n      'Origin Pincode      : %s' || chr(10) ||\r\n      'Destination Pincode : %s' || chr(10) ||\r\n      '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' || chr(10) ||\r\n      'Actual / Chargeable Weight : %s kg' || chr(10) ||\r\n      'Weight Billed by Courier   : %s kg' || chr(10) ||\r\n      'Weight Difference          : %s kg' || chr(10) ||\r\n      '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' || chr(10) ||\r\n      'Amount Billed              : Rs %.2f' || chr(10) ||\r\n      'Correct Amount (as per rate card) : Rs %.2f' || chr(10) ||\r\n      'Overcharge Amount          : Rs %.2f',\r\n      v_log.awb_number,\r\n      COALESCE(v_log.order_id, 'N/A'),\r\n      TO_CHAR(v_log.shipment_date, 'DD-Mon-YYYY'),\r\n      COALESCE(v_log.origin_pincode, 'N/A'),\r\n      COALESCE(v_log.destination_pincode, 'N/A'),\r\n      v_log.expected_weight,\r\n      v_log.billed_weight,\r\n      ROUND(v_log.billed_weight - v_log.expected_weight, 2),\r\n      v_log.billed_amount,\r\n      v_log.expected_amount,\r\n      v_log.overcharge_amount\r\n    )\r\n\r\n    -- ZONE MISMATCH\r\n    WHEN 'zone_mismatch' THEN format(\r\n      'DISCREPANCY DETAILS — ZONE MISCLASSIFICATION' || chr(10) ||\r\n      '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' || chr(10) ||\r\n      'AWB Number          : %s' || chr(10) ||\r\n      'Order ID            : %s' || chr(10) ||\r\n      'Shipment Date       : %s' || chr(10) ||\r\n      'Origin Pincode      : %s' || chr(10) ||\r\n      'Destination Pincode : %s' || chr(10) ||\r\n      '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' || chr(10) ||\r\n      'Zone Billed by Courier     : Zone %s' || chr(10) ||\r\n      'Correct Zone (per pincode) : Zone %s' || chr(10) ||\r\n      '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' || chr(10) ||\r\n      'Amount Billed              : Rs %.2f' || chr(10) ||\r\n      'Correct Amount (as per rate card) : Rs %.2f' || chr(10) ||\r\n      'Overcharge Amount          : Rs %.2f',\r\n      v_log.awb_number,\r\n      COALESCE(v_log.order_id, 'N/A'),\r\n      TO_CHAR(v_log.shipment_date, 'DD-Mon-YYYY'),\r\n      COALESCE(v_log.origin_pincode, 'N/A'),\r\n      COALESCE(v_log.destination_pincode, 'N/A'),\r\n      v_log.billed_zone,\r\n      v_log.expected_zone,\r\n      v_log.billed_amount,\r\n      v_log.expected_amount,\r\n      v_log.overcharge_amount\r\n    )\r\n\r\n    -- RTO OVERCHARGE\r\n    WHEN 'rto_overcharge' THEN format(\r\n      'DISCREPANCY DETAILS — RTO OVERCHARGE' || chr(10) ||\r\n      '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' || chr(10) ||\r\n      'AWB Number          : %s' || chr(10) ||\r\n      'Order ID            : %s' || chr(10) ||\r\n      'Shipment Date       : %s' || chr(10) ||\r\n      'Origin Pincode      : %s' || chr(10) ||\r\n      'Destination Pincode : %s' || chr(10) ||\r\n      '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' || chr(10) ||\r\n      'RTO Charge Billed          : Rs %.2f' || chr(10) ||\r\n      'Correct RTO Charge         : Rs %.2f' || chr(10) ||\r\n      'Overcharge Amount          : Rs %.2f',\r\n      v_log.awb_number,\r\n      COALESCE(v_log.order_id, 'N/A'),\r\n      TO_CHAR(v_log.shipment_date, 'DD-Mon-YYYY'),\r\n      COALESCE(v_log.origin_pincode, 'N/A'),\r\n      COALESCE(v_log.destination_pincode, 'N/A'),\r\n      v_log.billed_amount,\r\n      v_log.expected_amount,\r\n      v_log.overcharge_amount\r\n    )\r\n\r\n    -- WEIGHT + ZONE COMBINED\r\n    WHEN 'weight_zone_mismatch' THEN format(\r\n      'DISCREPANCY DETAILS — WEIGHT & ZONE MISMATCH' || chr(10) ||\r\n      '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' || chr(10) ||\r\n      'AWB Number          : %s' || chr(10) ||\r\n      'Order ID            : %s' || chr(10) ||\r\n      'Shipment Date       : %s' || chr(10) ||\r\n      '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' || chr(10) ||\r\n      'Actual Weight              : %s kg' || chr(10) ||\r\n      'Weight Billed              : %s kg' || chr(10) ||\r\n      'Zone Billed                : Zone %s' || chr(10) ||\r\n      'Correct Zone               : Zone %s' || chr(10) ||\r\n      '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' || chr(10) ||\r\n      'Amount Billed              : Rs %.2f' || chr(10) ||\r\n      'Correct Amount             : Rs %.2f' || chr(10) ||\r\n      'Total Overcharge           : Rs %.2f',\r\n      v_log.awb_number,\r\n      COALESCE(v_log.order_id, 'N/A'),\r\n      TO_CHAR(v_log.shipment_date, 'DD-Mon-YYYY'),\r\n      v_log.expected_weight,\r\n      v_log.billed_weight,\r\n      v_log.billed_zone,\r\n      v_log.expected_zone,\r\n      v_log.billed_amount,\r\n      v_log.expected_amount,\r\n      v_log.overcharge_amount\r\n    )\r\n\r\n    -- FALLBACK for any other type\r\n    ELSE format(\r\n      'DISCREPANCY DETAILS' || chr(10) ||\r\n      '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' || chr(10) ||\r\n      'AWB Number          : %s' || chr(10) ||\r\n      'Amount Billed       : Rs %.2f' || chr(10) ||\r\n      'Correct Amount      : Rs %.2f' || chr(10) ||\r\n      'Overcharge Amount   : Rs %.2f',\r\n      v_log.awb_number,\r\n      v_log.billed_amount,\r\n      v_log.expected_amount,\r\n      v_log.overcharge_amount\r\n    )\r\n  END;\r\n\r\n  -- ============================================================\r\n  -- DEMAND PARAGRAPH — firm, professional, same for all types\r\n  -- ============================================================\r\n  v_demand := format(\r\n    'In light of the above discrepancy, we formally request the following:' || chr(10) ||\r\n    chr(10) ||\r\n    '1. Issuance of a Credit Note for Rs %.2f against AWB %s within 7 business days.' || chr(10) ||\r\n    '2. A written acknowledgement of this dispute and the corrective action taken.' || chr(10) ||\r\n    '3. A review of our complete billing history to identify any similar discrepancies.' || chr(10) ||\r\n    chr(10) ||\r\n    'Please note that as per our service agreement, billing disputes must be acknowledged '\r\n    'within 48 hours and resolved within 7 business days. Failure to resolve this matter '\r\n    'within the stipulated timeframe will necessitate escalation to your regional account '\r\n    'manager and, if required, to the consumer dispute resolution forum.',\r\n    v_log.overcharge_amount,\r\n    v_log.awb_number\r\n  );\r\n\r\n  -- ============================================================\r\n  -- CLOSING — professional sign-off\r\n  -- ============================================================\r\n  v_closing := format(\r\n    'We value our partnership with %s and trust that this matter will be resolved '\r\n    'promptly and professionally. Please find the supporting shipment documents attached '\r\n    'for your reference.' || chr(10) ||\r\n    chr(10) ||\r\n    'Kindly acknowledge receipt of this email and provide a resolution timeline at your earliest convenience.' || chr(10) ||\r\n    chr(10) ||\r\n    'Warm regards,' || chr(10) ||\r\n    v_tenant.company_name || chr(10) ||\r\n    'Accounts & Logistics Team' || chr(10) ||\r\n    'Date: ' || v_today,\r\n    v_log.courier\r\n  );\r\n\r\n  -- ============================================================\r\n  -- ASSEMBLE FULL EMAIL BODY\r\n  -- ============================================================\r\n  v_body :=\r\n    v_greeting     || chr(10) || chr(10) ||\r\n    'Subject: '    || v_subject || chr(10) || chr(10) ||\r\n    'Date: '       || v_today || chr(10) || chr(10) ||\r\n    v_intro        || chr(10) || chr(10) ||\r\n    v_detail_block || chr(10) || chr(10) ||\r\n    v_demand       || chr(10) || chr(10) ||\r\n    v_closing;\r\n\r\n  -- ============================================================\r\n  -- SAVE TO DISPUTES TABLE\r\n  -- ============================================================\r\n  INSERT INTO disputes (\r\n    tenant_id,\r\n    audit_log_id,\r\n    awb_number,\r\n    courier,\r\n    overcharge_amount,\r\n    email_subject,\r\n    email_body,\r\n    status,\r\n    created_at,\r\n    updated_at\r\n  ) VALUES (\r\n    p_tenant_id,\r\n    p_audit_log_id,\r\n    v_log.awb_number,\r\n    v_log.courier,\r\n    v_log.overcharge_amount,\r\n    v_subject,\r\n    v_body,\r\n    'draft',\r\n    NOW(),\r\n    NOW()\r\n  )\r\n  ON CONFLICT (tenant_id, audit_log_id)\r\n  DO UPDATE SET\r\n    email_subject = EXCLUDED.email_subject,\r\n    email_body    = EXCLUDED.email_body,\r\n    updated_at    = NOW()\r\n  RETURNING id INTO v_dispute_id;\r\n\r\n  -- Log the action\r\n  INSERT INTO activity_logs (\r\n    tenant_id, user_id, action, entity_type, entity_id, details, created_at\r\n  ) VALUES (\r\n    p_tenant_id, p_generated_by, 'dispute_email_generated', 'dispute', v_dispute_id,\r\n    jsonb_build_object(\r\n      'awb_number', v_log.awb_number,\r\n      'courier', v_log.courier,\r\n      'discrepancy_type', v_log.discrepancy_type,\r\n      'overcharge_amount', v_log.overcharge_amount\r\n    ),\r\n    NOW()\r\n  );\r\n\r\n  RETURN jsonb_build_object(\r\n    'success',    true,\r\n    'dispute_id', v_dispute_id,\r\n    'subject',    v_subject,\r\n    'body',       v_body\r\n  );\r\n\r\nEXCEPTION WHEN OTHERS THEN\r\n  RETURN jsonb_build_object('success', false, 'error', SQLERRM);\r\nEND;\r\n"
  },
  {
    "routine_name": "generate_monthly_invoice",
    "routine_definition": "\r\nDECLARE\r\n  v_tenant RECORD;\r\n  v_total_recovered NUMERIC := 0;\r\n  v_platform_fee_pct NUMERIC;\r\n  v_platform_fee NUMERIC;\r\n  v_gst_amount NUMERIC;\r\n  v_total_amount NUMERIC;\r\n  v_invoice_number TEXT;\r\n  v_invoice_id UUID;\r\n  v_month_start DATE;\r\n  v_month_end DATE;\r\nBEGIN\r\n \r\n  -- Get tenant details including their pricing plan\r\n  SELECT * INTO v_tenant FROM tenants WHERE id = p_tenant_id;\r\n \r\n  IF NOT FOUND THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Tenant not found');\r\n  END IF;\r\n \r\n  -- Set billing period (full month)\r\n  v_month_start := DATE_TRUNC('month', p_billing_month)::DATE;\r\n  v_month_end := (DATE_TRUNC('month', p_billing_month) + INTERVAL '1 month - 1 day')::DATE;\r\n \r\n  -- Sum up all recovered amounts for this tenant this month\r\n  SELECT COALESCE(SUM(recovered_amount), 0) INTO v_total_recovered\r\n  FROM disputes\r\n  WHERE tenant_id = p_tenant_id\r\n    AND status = 'recovered'\r\n    AND resolved_at::DATE BETWEEN v_month_start AND v_month_end;\r\n \r\n  -- If nothing recovered, no invoice needed\r\n  IF v_total_recovered = 0 THEN\r\n    RETURN jsonb_build_object(\r\n      'success', true,\r\n      'message', 'No recoveries this month, no invoice generated',\r\n      'total_recovered', 0\r\n    );\r\n  END IF;\r\n \r\n  -- Determine platform fee percentage based on plan\r\n  v_platform_fee_pct := CASE v_tenant.plan\r\n    WHEN 'starter'      THEN 10.0\r\n    WHEN 'professional' THEN 8.0\r\n    WHEN 'enterprise'   THEN COALESCE(v_tenant.custom_fee_percentage, 7.0)\r\n    ELSE 10.0\r\n  END;\r\n \r\n  -- Calculate amounts\r\n  v_platform_fee := ROUND(v_total_recovered * (v_platform_fee_pct / 100), 2);\r\n  v_gst_amount   := ROUND(v_platform_fee * 0.18, 2);  -- 18% GST\r\n  v_total_amount := v_platform_fee + v_gst_amount;\r\n \r\n  -- Generate unique invoice number: AE-2026-03-0001\r\n  SELECT format('AE-%s-%s',\r\n    TO_CHAR(p_billing_month, 'YYYY-MM'),\r\n    LPAD((COUNT(*) + 1)::TEXT, 4, '0')\r\n  ) INTO v_invoice_number\r\n  FROM invoices\r\n  WHERE DATE_TRUNC('month', billing_period_start) = v_month_start;\r\n \r\n  -- Create the invoice record\r\n  INSERT INTO invoices (\r\n    tenant_id,\r\n    invoice_number,\r\n    billing_period_start,\r\n    billing_period_end,\r\n    total_recovered,\r\n    platform_fee_percentage,\r\n    platform_fee,\r\n    gst_amount,\r\n    total_amount,\r\n    status,\r\n    generated_by,\r\n    created_at\r\n  ) VALUES (\r\n    p_tenant_id,\r\n    v_invoice_number,\r\n    v_month_start,\r\n    v_month_end,\r\n    v_total_recovered,\r\n    v_platform_fee_pct,\r\n    v_platform_fee,\r\n    v_gst_amount,\r\n    v_total_amount,\r\n    'draft',\r\n    p_generated_by,\r\n    NOW()\r\n  ) RETURNING id INTO v_invoice_id;\r\n \r\n  -- Log the action\r\n  INSERT INTO activity_logs (\r\n    tenant_id, user_id, action, entity_type, entity_id, details, created_at\r\n  ) VALUES (\r\n    p_tenant_id, p_generated_by, 'invoice_generated', 'invoice', v_invoice_id,\r\n    jsonb_build_object(\r\n      'invoice_number', v_invoice_number,\r\n      'total_recovered', v_total_recovered,\r\n      'platform_fee', v_platform_fee,\r\n      'total_amount', v_total_amount\r\n    ),\r\n    NOW()\r\n  );\r\n \r\n  RETURN jsonb_build_object(\r\n    'success', true,\r\n    'invoice_id', v_invoice_id,\r\n    'invoice_number', v_invoice_number,\r\n    'total_recovered', v_total_recovered,\r\n    'platform_fee', v_platform_fee,\r\n    'gst_amount', v_gst_amount,\r\n    'total_amount', v_total_amount\r\n  );\r\n \r\nEXCEPTION WHEN OTHERS THEN\r\n  RETURN jsonb_build_object('success', false, 'error', SQLERRM);\r\nEND;\r\n"
  },
  {
    "routine_name": "get_my_claim",
    "routine_definition": "\n  SELECT COALESCE(\n    (auth.jwt() -> 'app_metadata' ->> claim),\n    ''\n  );\n"
  },
  {
    "routine_name": "get_my_profile",
    "routine_definition": "\r\nBEGIN\r\n  RETURN QUERY\r\n  SELECT \r\n    u.id,\r\n    u.email::text,\r\n    u.full_name::text,\r\n    u.role::text,\r\n    u.tenant_id,\r\n    u.is_active,\r\n    u.phone::text,\r\n    u.last_login,\r\n    u.notification_preferences,\r\n    u.created_at,\r\n    u.created_by,\r\n    u.updated_at,\r\n    u.updated_by\r\n  FROM public.users u\r\n  WHERE u.id = auth.uid();\r\nEND;\r\n"
  },
  {
    "routine_name": "get_user_profile_for_login",
    "routine_definition": "\r\n  SELECT \r\n    id,\r\n    email,\r\n    full_name,\r\n    role,\r\n    tenant_id,\r\n    COALESCE(is_active, true),\r\n    last_login,\r\n    phone,\r\n    notification_preferences\r\n  FROM public.users\r\n  WHERE id = lookup_user_id\r\n  LIMIT 1;\r\n"
  },
  {
    "routine_name": "handle_new_user",
    "routine_definition": "\nBEGIN\n  INSERT INTO public.users (id, email, full_name, role, tenant_id, is_active)\n  VALUES (\n    NEW.id,\n    NEW.email,\n    COALESCE(NEW.raw_user_meta_data ->> 'full_name', split_part(NEW.email, '@', 1)),\n    COALESCE(NEW.raw_user_meta_data ->> 'role', 'accountant'),\n    (NEW.raw_user_meta_data ->> 'tenant_id')::uuid,\n    true\n  )\n  ON CONFLICT (id) DO UPDATE SET\n    email = EXCLUDED.email,\n    full_name = COALESCE(EXCLUDED.full_name, public.users.full_name),\n    updated_at = now();\n  RETURN NEW;\nEND;\n"
  },
  {
    "routine_name": "log_activity",
    "routine_definition": "\nBEGIN\n  INSERT INTO public.activity_logs (\n    action, entity_type, entity_id, details,\n    old_values, new_values,\n    user_id, tenant_id\n  ) VALUES (\n    p_action, p_entity_type, p_entity_id, p_details,\n    p_old_values, p_new_values,\n    auth.uid(),\n    (SELECT tenant_id FROM public.users WHERE id = auth.uid())\n  );\nEND;\n"
  },
  {
    "routine_name": "notify_tenant_users",
    "routine_definition": "\nBEGIN\n  IF p_only_user_id IS NOT NULL THEN\n    INSERT INTO public.notifications (user_id, tenant_id, title, message, type, link)\n    VALUES (p_only_user_id, p_tenant_id, p_title, p_message, p_type, p_link);\n  ELSE\n    INSERT INTO public.notifications (user_id, tenant_id, title, message, type, link)\n    SELECT id, p_tenant_id, p_title, p_message, p_type, p_link\n    FROM public.users\n    WHERE tenant_id = p_tenant_id AND is_active = true;\n  END IF;\nEND;\n"
  },
  {
    "routine_name": "prevent_self_role_escalation",
    "routine_definition": "\nDECLARE\n  caller_role text;\nBEGIN\n  caller_role := COALESCE((current_setting('request.jwt.claims', true)::jsonb -> 'app_metadata' ->> 'role'), '');\n  \n  -- Platform admins can change anything\n  IF caller_role = 'platform_admin' THEN\n    RETURN NEW;\n  END IF;\n\n  -- Tenant admins can change role for team members (handled by RLS)\n  IF caller_role = 'tenant_admin' AND NEW.id <> auth.uid() THEN\n    RETURN NEW;\n  END IF;\n\n  -- For self-updates by non-admin users: block changes to sensitive columns\n  IF NEW.role IS DISTINCT FROM OLD.role THEN\n    RAISE EXCEPTION 'Cannot change your own role';\n  END IF;\n  IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id THEN\n    RAISE EXCEPTION 'Cannot change your own tenant';\n  END IF;\n  IF NEW.is_active IS DISTINCT FROM OLD.is_active THEN\n    RAISE EXCEPTION 'Cannot change your own active status';\n  END IF;\n\n  RETURN NEW;\nEND;\n"
  },
  {
    "routine_name": "process_csv_upload",
    "routine_definition": "\r\nDECLARE\r\n  v_shipment JSONB;\r\n  v_rate_card JSONB;\r\n  v_courier TEXT;\r\n  v_actual_weight NUMERIC;\r\n  v_volumetric_weight NUMERIC;\r\n  v_chargeable_weight NUMERIC;\r\n  v_billed_weight NUMERIC;\r\n  v_billed_amount NUMERIC;\r\n  v_expected_amount NUMERIC;\r\n  v_overcharge NUMERIC;\r\n  v_billed_zone TEXT;\r\n  v_expected_zone TEXT;\r\n  v_rate_per_kg NUMERIC;\r\n  v_rto_percentage NUMERIC;\r\n  v_discrepancy_type TEXT;\r\n  v_processed INT := 0;\r\n  v_discrepancies INT := 0;\r\n  v_shipment_id UUID;\r\n  v_awb TEXT;\r\nBEGIN\r\n \r\n  -- Loop through every shipment row from the CSV\r\n  FOR v_shipment IN SELECT * FROM jsonb_array_elements(p_shipments)\r\n  LOOP\r\n    v_awb := v_shipment->>'awb_number';\r\n    v_courier := v_shipment->>'courier';\r\n    v_actual_weight := (v_shipment->>'actual_weight')::NUMERIC;\r\n    v_billed_weight := (v_shipment->>'billed_weight')::NUMERIC;\r\n    v_billed_amount := (v_shipment->>'billed_amount')::NUMERIC;\r\n    v_billed_zone := v_shipment->>'billed_zone';\r\n \r\n    -- Get this tenant's rate card for this courier\r\n    SELECT rate_structure INTO v_rate_card\r\n    FROM rate_cards\r\n    WHERE tenant_id = p_tenant_id\r\n      AND courier = v_courier\r\n      AND is_active = true\r\n    LIMIT 1;\r\n \r\n    -- Skip if no rate card exists for this courier\r\n    IF v_rate_card IS NULL THEN\r\n      CONTINUE;\r\n    END IF;\r\n \r\n    -- Insert shipment record\r\n    INSERT INTO shipments (\r\n      tenant_id, awb_number, courier, order_id,\r\n      actual_weight, billed_weight, billed_amount,\r\n      origin_pincode, destination_pincode, billed_zone,\r\n      shipment_date, is_rto, uploaded_by, created_at\r\n    ) VALUES (\r\n      p_tenant_id,\r\n      v_awb,\r\n      v_courier,\r\n      v_shipment->>'order_id',\r\n      v_actual_weight,\r\n      v_billed_weight,\r\n      v_billed_amount,\r\n      v_shipment->>'origin_pincode',\r\n      v_shipment->>'destination_pincode',\r\n      v_billed_zone,\r\n      (v_shipment->>'shipment_date')::DATE,\r\n      COALESCE((v_shipment->>'is_rto')::BOOLEAN, false),\r\n      p_uploaded_by,\r\n      NOW()\r\n    )\r\n    ON CONFLICT (tenant_id, awb_number) DO NOTHING\r\n    RETURNING id INTO v_shipment_id;\r\n \r\n    IF v_shipment_id IS NULL THEN\r\n      v_processed := v_processed + 1;\r\n      CONTINUE; -- Already processed this AWB\r\n    END IF;\r\n \r\n    -- ================================================\r\n    -- CHECK 1: WEIGHT DISCREPANCY\r\n    -- ================================================\r\n    -- Volumetric weight = L x W x H / 5000\r\n    v_volumetric_weight := COALESCE(\r\n      ((v_shipment->>'length')::NUMERIC *\r\n       (v_shipment->>'width')::NUMERIC *\r\n       (v_shipment->>'height')::NUMERIC) / 5000,\r\n      0\r\n    );\r\n \r\n    -- Chargeable weight = whichever is higher\r\n    v_chargeable_weight := GREATEST(v_actual_weight, v_volumetric_weight);\r\n \r\n    -- Get rate per kg from rate card\r\n    v_rate_per_kg := (v_rate_card->'weight_slabs'->0->>'rate_per_kg')::NUMERIC;\r\n \r\n    -- Find the right rate slab based on chargeable weight\r\n    SELECT (slab->>'rate_per_kg')::NUMERIC INTO v_rate_per_kg\r\n    FROM jsonb_array_elements(v_rate_card->'weight_slabs') AS slab\r\n    WHERE (slab->>'min_weight')::NUMERIC <= v_chargeable_weight\r\n      AND (slab->>'max_weight')::NUMERIC >= v_chargeable_weight\r\n    LIMIT 1;\r\n \r\n    v_expected_amount := v_chargeable_weight * COALESCE(v_rate_per_kg, 0);\r\n \r\n    -- Allow 0.5 kg tolerance (courier contracts usually have this buffer)\r\n    IF (v_billed_weight - v_chargeable_weight) > 0.5 THEN\r\n      v_overcharge := v_billed_amount - v_expected_amount;\r\n      IF v_overcharge > 0 THEN\r\n        INSERT INTO audit_logs (\r\n          tenant_id, shipment_id, awb_number, courier,\r\n          discrepancy_type, billed_amount, expected_amount,\r\n          overcharge_amount, billed_weight, expected_weight,\r\n          status, created_at\r\n        ) VALUES (\r\n          p_tenant_id, v_shipment_id, v_awb, v_courier,\r\n          'weight_mismatch', v_billed_amount, v_expected_amount,\r\n          v_overcharge, v_billed_weight, v_chargeable_weight,\r\n          'pending', NOW()\r\n        );\r\n        v_discrepancies := v_discrepancies + 1;\r\n      END IF;\r\n    END IF;\r\n \r\n    -- ================================================\r\n    -- CHECK 2: ZONE DISCREPANCY\r\n    -- ================================================\r\n    SELECT zone INTO v_expected_zone\r\n    FROM pincode_zones\r\n    WHERE origin_pincode = v_shipment->>'origin_pincode'\r\n      AND destination_pincode = v_shipment->>'destination_pincode'\r\n      AND courier = v_courier\r\n    LIMIT 1;\r\n \r\n    IF v_expected_zone IS NOT NULL AND v_billed_zone != v_expected_zone THEN\r\n      -- Calculate overcharge based on zone rate difference\r\n      DECLARE\r\n        v_billed_zone_rate NUMERIC;\r\n        v_correct_zone_rate NUMERIC;\r\n      BEGIN\r\n        v_billed_zone_rate := (v_rate_card->'zone_rates'->v_billed_zone->>'rate_per_kg')::NUMERIC;\r\n        v_correct_zone_rate := (v_rate_card->'zone_rates'->v_expected_zone->>'rate_per_kg')::NUMERIC;\r\n        v_overcharge := (v_billed_zone_rate - v_correct_zone_rate) * v_chargeable_weight;\r\n \r\n        IF v_overcharge > 0 THEN\r\n          INSERT INTO audit_logs (\r\n            tenant_id, shipment_id, awb_number, courier,\r\n            discrepancy_type, billed_amount, expected_amount,\r\n            overcharge_amount, billed_zone, expected_zone,\r\n            status, created_at\r\n          ) VALUES (\r\n            p_tenant_id, v_shipment_id, v_awb, v_courier,\r\n            'zone_mismatch', v_billed_amount,\r\n            v_billed_amount - v_overcharge,\r\n            v_overcharge, v_billed_zone, v_expected_zone,\r\n            'pending', NOW()\r\n          );\r\n          v_discrepancies := v_discrepancies + 1;\r\n        END IF;\r\n      END;\r\n    END IF;\r\n \r\n    -- ================================================\r\n    -- CHECK 3: RTO OVERCHARGE\r\n    -- ================================================\r\n    IF (v_shipment->>'is_rto')::BOOLEAN = true THEN\r\n      v_rto_percentage := COALESCE(\r\n        (v_rate_card->>'rto_percentage')::NUMERIC, 50\r\n      );\r\n      -- Expected RTO = forward charge × RTO percentage\r\n      v_expected_amount := v_billed_amount * (v_rto_percentage / 100);\r\n      v_overcharge := v_billed_amount - v_expected_amount;\r\n \r\n      IF v_overcharge > 10 THEN -- Min threshold ₹10\r\n        INSERT INTO audit_logs (\r\n          tenant_id, shipment_id, awb_number, courier,\r\n          discrepancy_type, billed_amount, expected_amount,\r\n          overcharge_amount, status, created_at\r\n        ) VALUES (\r\n          p_tenant_id, v_shipment_id, v_awb, v_courier,\r\n          'rto_overcharge', v_billed_amount, v_expected_amount,\r\n          v_overcharge, 'pending', NOW()\r\n        );\r\n        v_discrepancies := v_discrepancies + 1;\r\n      END IF;\r\n    END IF;\r\n \r\n    v_processed := v_processed + 1;\r\n  END LOOP;\r\n \r\n  -- Return summary\r\n  RETURN jsonb_build_object(\r\n    'success', true,\r\n    'processed', v_processed,\r\n    'discrepancies_found', v_discrepancies,\r\n    'message', format('Processed %s shipments, found %s discrepancies', v_processed, v_discrepancies)\r\n  );\r\n \r\nEXCEPTION WHEN OTHERS THEN\r\n  RETURN jsonb_build_object(\r\n    'success', false,\r\n    'error', SQLERRM\r\n  );\r\nEND;\r\n"
  },
  {
    "routine_name": "resolve_zone_mapping",
    "routine_definition": "\r\nDECLARE\r\n  v_src_prefix    INTEGER;\r\n  v_dst_prefix    INTEGER;\r\n  v_src_circle    TEXT;\r\n  v_dst_circle    TEXT;\r\n  v_zone          TEXT;\r\n  v_is_fallback   BOOLEAN := FALSE;\r\n  v_src_int       INTEGER;\r\n  v_dst_int       INTEGER;\r\nBEGIN\r\n  -- Step 1: Sanitise and extract 3-digit prefix\r\n  -- Strip any spaces or non-numeric characters defensively\r\n  v_src_int := SUBSTRING(REGEXP_REPLACE(p_source_pincode, '[^0-9]', '', 'g'), 1, 6)::INTEGER;\r\n  v_dst_int := SUBSTRING(REGEXP_REPLACE(p_dest_pincode,   '[^0-9]', '', 'g'), 1, 6)::INTEGER;\r\n\r\n  v_src_prefix := v_src_int / 1000;  -- first 3 digits of 6-digit pin\r\n  v_dst_prefix := v_dst_int / 1000;\r\n\r\n  -- Step 2: Resolve source circle from prefix map\r\n  SELECT circle INTO v_src_circle\r\n  FROM   pincode_circle_map\r\n  WHERE  v_src_prefix BETWEEN prefix_start AND prefix_end\r\n  ORDER BY prefix_start DESC  -- more specific range wins\r\n  LIMIT  1;\r\n\r\n  -- Step 3: Resolve destination circle\r\n  SELECT circle INTO v_dst_circle\r\n  FROM   pincode_circle_map\r\n  WHERE  v_dst_prefix BETWEEN prefix_start AND prefix_end\r\n  ORDER BY prefix_start DESC\r\n  LIMIT  1;\r\n\r\n  -- Step 4: Handle unrecognised pincodes with conservative fallback\r\n  IF v_src_circle IS NULL THEN\r\n    v_src_circle  := 'Remote';\r\n    v_is_fallback := TRUE;\r\n  END IF;\r\n\r\n  IF v_dst_circle IS NULL THEN\r\n    v_dst_circle  := 'Remote';\r\n    v_is_fallback := TRUE;\r\n  END IF;\r\n\r\n  -- Step 5: Special override — same 6-digit pincode = Local/Within regardless of circle\r\n  IF p_source_pincode = p_dest_pincode THEN\r\n    v_zone := 'Within';\r\n    v_src_circle := COALESCE(v_src_circle, 'Within');\r\n    v_dst_circle := v_src_circle;\r\n  ELSE\r\n    -- Step 6: Matrix lookup\r\n    SELECT zcm.zone_code INTO v_zone\r\n    FROM   zone_circle_matrix zcm\r\n    WHERE  zcm.origin_circle      = v_src_circle\r\n    AND    zcm.destination_circle = v_dst_circle;\r\n\r\n    -- Safety net if matrix has a gap (should never happen with full seed)\r\n    IF v_zone IS NULL THEN\r\n      v_zone        := 'Zone_C';\r\n      v_is_fallback := TRUE;\r\n    END IF;\r\n  END IF;\r\n\r\n  -- Step 7: UPSERT into zone_mapping — idempotent, safe to call repeatedly\r\n  INSERT INTO zone_mapping (\r\n    tenant_id, courier_id,\r\n    source_pincode, destination_pincode,\r\n    source_circle,  destination_circle,\r\n    zone_code,      is_fallback\r\n  )\r\n  VALUES (\r\n    p_tenant_id, p_courier_id,\r\n    p_source_pincode, p_dest_pincode,\r\n    v_src_circle,     v_dst_circle,\r\n    v_zone,           v_is_fallback\r\n  )\r\n  ON CONFLICT (tenant_id, courier_id, source_pincode, destination_pincode)\r\n  DO UPDATE SET\r\n    zone_code          = EXCLUDED.zone_code,\r\n    source_circle      = EXCLUDED.source_circle,\r\n    destination_circle = EXCLUDED.destination_circle,\r\n    is_fallback        = EXCLUDED.is_fallback,\r\n    resolved_at        = NOW();\r\n\r\n  -- Step 8: Return the resolved values to the caller (n8n reads this)\r\n  RETURN QUERY SELECT v_zone, v_src_circle, v_dst_circle, v_is_fallback;\r\nEND;\r\n"
  },
  {
    "routine_name": "resolve_zone_mapping_batch",
    "routine_definition": "\r\nBEGIN\r\n  RETURN QUERY\r\n  SELECT\r\n    pair->>'src' AS src,\r\n    pair->>'dst' AS dst,\r\n    COALESCE(\r\n      zm.zone,\r\n      'Zone_C'\r\n    ) AS zone_code\r\n  FROM jsonb_array_elements(p_pairs) AS pair\r\n  LEFT JOIN zone_mappings zm\r\n    ON zm.tenant_id = p_tenant_id\r\n    AND zm.courier_name = p_courier_id\r\n    AND zm.origin_pincode = pair->>'src'\r\n    AND zm.destination_pincode = pair->>'dst';\r\nEND;\r\n"
  },
  {
    "routine_name": "set_updated_at",
    "routine_definition": "\nBEGIN NEW.updated_at = now(); RETURN NEW; END;\n"
  },
  {
    "routine_name": "sync_claims_on_user_insert",
    "routine_definition": "\r\nBEGIN\r\n  RETURN NEW;\r\nEXCEPTION WHEN OTHERS THEN\r\n  RETURN NEW;\r\nEND;\r\n"
  },
  {
    "routine_name": "sync_claims_on_user_update",
    "routine_definition": "\r\nBEGIN\r\n  -- Intentionally does NOT update auth.users to avoid deadlock with GoTrue\r\n  -- JWT claims are embedded by the custom_access_token_hook instead\r\n  RETURN NEW;\r\nEXCEPTION WHEN OTHERS THEN\r\n  RETURN NEW;\r\nEND;\r\n"
  },
  {
    "routine_name": "trg_notify_dispute_change",
    "routine_definition": "\nBEGIN\n  IF (OLD.dispute_status IS DISTINCT FROM NEW.dispute_status) THEN\n    -- Notify when dispute is raised\n    IF NEW.dispute_status = 'raised' THEN\n      PERFORM public.notify_tenant_users(\n        NEW.tenant_id,\n        'Dispute raised',\n        format('Dispute raised for order %s (AWB: %s) — ₹%s discrepancy.', NEW.order_id, COALESCE(NEW.awb, 'N/A'), COALESCE(NEW.discrepancy_amount, 0)),\n        'warning',\n        '/tenant/disputes'\n      );\n    -- Notify when recovery is recorded\n    ELSIF NEW.dispute_status = 'recovered' THEN\n      PERFORM public.notify_tenant_users(\n        NEW.tenant_id,\n        'Recovery recorded',\n        format('₹%s recovered for order %s (AWB: %s).', COALESCE(NEW.recovery_amount, 0), NEW.order_id, COALESCE(NEW.awb, 'N/A')),\n        'success',\n        '/tenant/recoveries'\n      );\n    -- Notify when dispute is rejected\n    ELSIF NEW.dispute_status = 'rejected' THEN\n      PERFORM public.notify_tenant_users(\n        NEW.tenant_id,\n        'Dispute rejected',\n        format('Dispute for order %s (AWB: %s) was rejected.', NEW.order_id, COALESCE(NEW.awb, 'N/A')),\n        'error',\n        '/tenant/disputes'\n      );\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n"
  },
  {
    "routine_name": "trg_notify_invite_accepted",
    "routine_definition": "\nBEGIN\n  IF (OLD.invite_status IS DISTINCT FROM NEW.invite_status) AND NEW.invite_status = 'accepted' THEN\n    PERFORM public.notify_tenant_users(\n      NEW.tenant_id,\n      'New team member joined',\n      format('%s has accepted the invitation and joined your team.', NEW.email),\n      'info',\n      '/tenant/team',\n      NEW.invited_by\n    );\n  END IF;\n  RETURN NEW;\nEND;\n"
  },
  {
    "routine_name": "trg_notify_upload_batch",
    "routine_definition": "\nBEGIN\n  -- Only fire when status changes to completed or failed\n  IF (OLD.status IS DISTINCT FROM NEW.status) THEN\n    IF NEW.status = 'completed' THEN\n      PERFORM public.notify_tenant_users(\n        NEW.tenant_id,\n        'CSV upload completed',\n        format('File \"%s\" processed: %s rows, %s discrepancies found.', NEW.filename, COALESCE(NEW.processed_rows, 0), COALESCE(NEW.discrepancy_rows, 0)),\n        'success',\n        '/tenant/upload-history',\n        NEW.created_by\n      );\n    ELSIF NEW.status = 'failed' THEN\n      PERFORM public.notify_tenant_users(\n        NEW.tenant_id,\n        'CSV upload failed',\n        format('File \"%s\" failed to process. Check upload history for details.', NEW.filename),\n        'error',\n        '/tenant/upload-history',\n        NEW.created_by\n      );\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n"
  },
  {
    "routine_name": "update_dispute_status",
    "routine_definition": "\r\nDECLARE\r\n  v_dispute RECORD;\r\n  v_tenant_id UUID;\r\n  v_old_status TEXT;\r\nBEGIN\r\n \r\n  -- Get current dispute details\r\n  SELECT * INTO v_dispute FROM disputes WHERE id = p_dispute_id;\r\n \r\n  IF NOT FOUND THEN\r\n    RETURN jsonb_build_object('success', false, 'error', 'Dispute not found');\r\n  END IF;\r\n \r\n  v_old_status := v_dispute.status;\r\n  v_tenant_id := v_dispute.tenant_id;\r\n \r\n  -- Validate status transition\r\n  -- Draft can go to Raised\r\n  -- Raised can go to Recovered or Rejected\r\n  IF NOT (\r\n    (v_old_status = 'draft' AND p_new_status = 'raised') OR\r\n    (v_old_status = 'raised' AND p_new_status IN ('recovered', 'rejected')) OR\r\n    (v_old_status = 'raised' AND p_new_status = 'escalated')\r\n  ) THEN\r\n    RETURN jsonb_build_object(\r\n      'success', false,\r\n      'error', format('Cannot move from %s to %s', v_old_status, p_new_status)\r\n    );\r\n  END IF;\r\n \r\n  -- Update the dispute\r\n  UPDATE disputes SET\r\n    status = p_new_status,\r\n    recovered_amount = CASE WHEN p_new_status = 'recovered' THEN p_recovered_amount ELSE recovered_amount END,\r\n    notes = COALESCE(p_notes, notes),\r\n    follow_up_date = COALESCE(p_follow_up_date, follow_up_date),\r\n    raised_at = CASE WHEN p_new_status = 'raised' THEN NOW() ELSE raised_at END,\r\n    resolved_at = CASE WHEN p_new_status IN ('recovered', 'rejected') THEN NOW() ELSE resolved_at END,\r\n    updated_at = NOW()\r\n  WHERE id = p_dispute_id;\r\n \r\n  -- Log the status change in activity_logs\r\n  INSERT INTO activity_logs (\r\n    tenant_id, user_id, action, entity_type, entity_id,\r\n    details, created_at\r\n  ) VALUES (\r\n    v_tenant_id,\r\n    p_updated_by,\r\n    'dispute_status_changed',\r\n    'dispute',\r\n    p_dispute_id,\r\n    jsonb_build_object(\r\n      'old_status', v_old_status,\r\n      'new_status', p_new_status,\r\n      'awb_number', v_dispute.awb_number,\r\n      'recovered_amount', p_recovered_amount\r\n    ),\r\n    NOW()\r\n  );\r\n \r\n  -- If recovered, create credit note record\r\n  IF p_new_status = 'recovered' AND p_recovered_amount > 0 THEN\r\n    INSERT INTO credit_notes (\r\n      tenant_id, dispute_id, awb_number, courier,\r\n      amount, status, created_at\r\n    ) VALUES (\r\n      v_tenant_id,\r\n      p_dispute_id,\r\n      v_dispute.awb_number,\r\n      v_dispute.courier,\r\n      p_recovered_amount,\r\n      'issued',\r\n      NOW()\r\n    );\r\n  END IF;\r\n \r\n  RETURN jsonb_build_object(\r\n    'success', true,\r\n    'dispute_id', p_dispute_id,\r\n    'old_status', v_old_status,\r\n    'new_status', p_new_status\r\n  );\r\n \r\nEXCEPTION WHEN OTHERS THEN\r\n  RETURN jsonb_build_object('success', false, 'error', SQLERRM);\r\nEND;\r\n"
  },
  {
